nsMsgDBFolder::GetChildNamed(const nsACString& aName, nsIMsgFolder** aChild) {
  NS_ENSURE_STATE(!aName.IsEmpty());
  NS_ENSURE_ARG_POINTER(aChild);
  nsTArray<RefPtr<nsIMsgFolder>> dummy;
  GetSubFolders(dummy);  // initialize mSubFolders
  *aChild = nullptr;

  for (nsIMsgFolder* child : mSubFolders) {
    nsCString folderName;
    nsresult rv = child->GetName(folderName);
    // case-insensitive compare is probably LCD across OS filesystems
    if (NS_SUCCEEDED(rv) &&
        folderName.Equals(aName, nsCaseInsensitiveUTF8StringComparator)) {
      NS_ADDREF(*aChild = child);
      return NS_OK;
    }
  }
  return NS_OK;

const rootFolder = localAccountUtils.rootFolder;
gDraftFolder =
  rootFolder.getChildNamed("Drafts") ||
  rootFolder.createLocalSubfolder("Drafts");
// Make sure the drafts folder is empty
// Clear all messages
const msgs = [...gDraftFolder.msgDatabase.enumerateMessages()];
if (msgs.length > 0) {
  gDraftFolder.deleteMessages(msgs, null, true, false, null, false);
}
